+        String modelText,
+        String filter,
+        String modelId,
+        String denseVectorFieldName
+    ) throws IOException {
+        Request request = new Request("GET", index + "/_search?error_trace=true");
+
+        String termsFilter = Strings.format("""
+            {"term": {"filter_field": "%s"}}
+            """, filter);
+
+        request.setJsonEntity(Strings.format("""
+            {
+              "knn": {
+                  "field": "%s",
+                  "k": 5,
+                  "num_candidates": 10,
+                  "filter": %s,
+                  "query_vector_builder": {
+                    "text_embedding": {
+                      "model_id": "%s",
